def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = sum(1 for x in opp if x == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for x in me if x == 'C')
    my_d = n - my_c
    last_opp = opp[-1]
    last_me = me[-1]

    if n < 4:
        if last_opp == 'D':
            return 'D'
        return 'C'

    coop_rate = opp_c / n

    if opp_d == 0:
        if n >= 97:
            return 'D'
        if n >= 90 and rng.random() < 0.7:
            return 'D'
        if n >= 80 and rng.random() < 0.25:
            return 'D'
        return 'C'

    if n >= 12 and opp_d <= 1:
        if n >= 97:
            return 'D'
        if n >= 90 and rng.random() < 0.6:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if opp_c == 0:
        return 'D'

    if n >= 15:
        if coop_rate < 0.15:
            if rng.random() < 0.05:
                return 'C'
            return 'D'
        if coop_rate < 0.35:
            if last_opp == 'C':
                return 'C' if rng.random() < 0.4 else 'D'
            return 'D'

    if last_opp == 'D':
        streak = 0
        for x in reversed(opp):
            if x == 'D':
                streak += 1
            else:
                break
        if streak >= 3:
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        if last_me == 'C':
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    recent_w = min(10, n)
    recent_opp_c = sum(1 for x in opp[-recent_w:] if x == 'C')
    recent_rate = recent_opp_c / recent_w

    if n >= 95 and coop_rate > 0.7:
        return 'D'
    if n >= 88 and coop_rate > 0.75 and rng.random() < 0.5:
        return 'D'

    if recent_rate >= 0.8:
        if coop_rate > 0.7 and my_d > 0 and rng.random() < 0.08:
            return 'D'
        return 'C'

    if recent_rate >= 0.5:
        if last_opp == 'C' and last_me == 'D':
            return 'C'
        return 'C' if rng.random() < 0.85 else 'D'

    if last_me == 'C' and last_opp == 'C':
        if recent_rate < 0.3 and rng.random() < 0.4:
            return 'D'
        return 'C'

    if rng.random() < 0.3:
        return 'C'
    return 'D'
